[CmdletBinding()]
param([Parameter(Mandatory)][string]$PromptText,[string]$OutputPath='ES/Output/WebPageStudio/bootstrap/round-01-intake.json')
$ErrorActionPreference='Stop';$root=(Resolve-Path '.').Path;$full=[IO.Path]::GetFullPath((Join-Path $root $OutputPath));if(-not $full.StartsWith($root+'\',[StringComparison]::OrdinalIgnoreCase)){throw 'OutputPath must remain under project root.'};New-Item -ItemType Directory -Force (Split-Path $full)|Out-Null;$bytes=[Text.UTF8Encoding]::new($false).GetBytes($PromptText);$hex=(-join(([Security.Cryptography.SHA256]::Create().ComputeHash($bytes))|%{$_.ToString('x2')}));$r=[ordered]@{schemaVersion=1;recordType='RequirementIntakeReceipt';roundId='web-generation-round-01';stageId='requirement-intake';status='accepted';inputHash=$hex;rawPrompt=$PromptText;allowedScope=@('requirement intake receipt');forbiddenScope=@('FocusContext','TaskContext','Knowledge','SubAgent','ABCD','generation','runtime','network','Unity','Git','release');unknowns=@('business objective pending','acceptance signals pending');acceptanceSignals=@('raw prompt preserved','strict UTF-8 hash','scope boundary explicit');aiAnalysis='Analyze only intake completeness and authorization; do not invent business intent.';execution='Persist the intake receipt and stop before Round 02.';decision='accepted-for-focus-proposal';returnReceipt=[ordered]@{status='accepted';path=$OutputPath;hash=$hex};nonClaims=@('not requirement understanding','not user acceptance','not downstream execution')};[IO.File]::WriteAllText($full,($r|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false));$r|ConvertTo-Json -Depth 8
